arguments.command:
cd /workspace && python3 - <<'PY'
import os, stat
from pathlib import Path
root=Path('submission')
entries=0; total=0; pyc=[]
for base,dirs,files in os.walk(root, followlinks=False):
    for name in dirs+files:
        p=Path(base)/name; st=p.lstat(); entries+=1
        if stat.S_ISDIR(st.st_mode):
            if name=='__pycache__': pyc.append(str(p))
            continue
        if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:
            print('BAD', p)
        total+=st.st_size
print('entries', entries, 'bytes', total, 'pycache', pyc)
PY
